const handleBlockUser = async (userId) => {
    await db.collection('users').doc(currentUser.uid).update({ blockedUsers: firebase.firestore.FieldValue.arrayUnion(userId) });
    currentUser.blockedUsers.push(userId);
    showUserProfile(userId);
};
const handleUnblockUser = async (userId) => {
    await db.collection('users').doc(currentUser.uid).update({ blockedUsers: firebase.firestore.FieldValue.arrayRemove(userId) });
    currentUser.blockedUsers = currentUser.blockedUsers.filter(id => id !== userId);
    showUserProfile(userId);
};
const handleAcceptInvite = async (inviteId, inviteData) => {
    if (inviteData.type === 'friend') {
        const batch = db.batch();
        batch.update(db.collection('users').doc(currentUser.uid), { friends: firebase.firestore.FieldValue.arrayUnion(inviteData.fromId) });
        batch.update(db.collection('users').doc(inviteData.fromId), { friends: firebase.firestore.FieldValue.arrayUnion(currentUser.uid) });
        await batch.commit();
    } else {
        const serverRef = db.collection('servers').doc(inviteData.serverId);
        await serverRef.update({ members: firebase.firestore.FieldValue.arrayUnion(currentUser.uid) });
        await serverRef.collection('members').doc(currentUser.uid).set({ roles: ['default'] });
    }
    await db.collection('invitations').doc(inviteId).delete();
};
const handleDeclineInvite = async (inviteId) => { await db.collection('invitations').doc(inviteId).delete(); };
const handleRemoveFriend = async (friendId, friendName) => {
