const loadServers = () => {
    if (serversUnsubscribe) serversUnsubscribe();
    if (!currentUser || !db) return;
    serversUnsubscribe = db.collection('servers')
        .where('members', 'array-contains', currentUser.uid)
        .onSnapshot((snapshot: any) => {
            const servers = snapshot.docs.map((d: any) => ({ id: d.id, ...d.data() }));
            renderServers(servers);
        });
};

const loadFriends = () => {
    if (friendsUnsubscribe) friendsUnsubscribe();
    if (!currentUser || !db) return;
    friendsUnsubscribe = db.collection('users').doc(currentUser.uid).onSnapshot(async (doc: any) => {
        if (doc.exists) {
            const data = doc.data();
            const fIds = data.friends || [];
            if (fIds.length > 0) {
                const fDocs = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', fIds).get();
                const friends = fDocs.docs.map((d: any) => ({ id: d.id, ...d.data() }));
                renderFriends(friends);
            } else {
                renderFriends([]);
            }
        }
    });
};

const setupInvitationsListener = () => {
    if (invitationsUnsubscribe) invitationsUnsubscribe();
    if (!currentUser || !db) return;
    invitationsUnsubscribe = db.collection('invitations')
        .where('toId', '==', currentUser.uid)
        .where('status', '==', 'pending')
        .onSnapshot((snapshot: any) => {
            const badge = getEl('pending-invites-badge');
            if (badge) {
                const count = snapshot.docs.length;
                badge.textContent = count.toString();
                badge.classList.toggle('hidden', count === 0);
