                    const displayName = user.displayName || user.email.split('@')[0];
                    const photoURL = user.photoURL || `https://i.pravatar.cc/64?u=${user.uid}`;
                    const shortCode = generateShortCode();
                    await userDocRef.set({ displayName, photoURL, shortCode, status: 'online', friends: [], blockedUsers: [] });
                    currentUser = { uid: user.uid, displayName, photoURL, shortCode, email: user.email };
                } else {
                    const userData = userDoc.data();
                    let sc = userData.shortCode || generateShortCode();
                    if (!userData.shortCode) await userDocRef.update({ shortCode: sc });
                    await userDocRef.update({ status: 'online' });
                    currentUser = { uid: user.uid, displayName: userData.displayName, photoURL: userData.photoURL, shortCode: sc, email: user.email };
                }

                addClass('login-view', 'hidden');
                removeClass('app-view', 'hidden');
                renderUserInfo();
                loadServers();
                loadFriends();
                setupPresence();
                setupCallListener();
                setupInvitationsListener();
                selectHome();
            } catch (error) {
                console.error(error);
                removeClass('app-error-overlay', 'hidden');
            }
        } else {
            currentUser = null;
            removeClass('login-view', 'hidden');
            addClass('app-view', 'hidden');
            if (serversUnsubscribe) serversUnsubscribe();
            if (channelUnsubscribe) channelUnsubscribe();
            if (messageUnsubscribe) messageUnsubscribe();
        }
    });
}

