const selectServer = async (serverId: string) => {
    if (activeServerId === serverId && activeView === 'servers') return;
    activeView = 'servers';
    activeServerId = serverId;
    activeChannelId = null;

    if (channelUnsubscribe) channelUnsubscribe();
    if (usersUnsubscribe) usersUnsubscribe();
    if (messageUnsubscribe) messageUnsubscribe();

    setDisplay('home-view', 'none');
    setDisplay('channel-list-panel', 'flex');
    setDisplay('user-list-aside', 'block');
    setDisplay('chat-view', 'none');

    const ph = getEl('placeholder-view');
    if (ph) {
        ph.style.display = 'flex';
        ph.innerHTML = `<div class="text-center text-gray-400"><h2 class="text-2xl font-bold">Select a channel</h2><p class="mt-2">Pick a channel to get the conversation started.</p></div>`;
    }

    if (!db) return;
    const serverRef = db.collection('servers').doc(serverId);

    usersUnsubscribe = serverRef.onSnapshot(async (doc: any) => {
        if (doc.exists) {
            const serverData = doc.data();
            activeServerData = serverData;
            activeServerRoles = serverData.roles || {};
            activeServerRoleOrder = serverData.roleOrder || Object.keys(activeServerRoles);

            const membersSnapshot = await serverRef.collection('members').get();
            activeServerMembers = {};
            membersSnapshot.forEach((mdoc: any) => activeServerMembers[mdoc.id] = mdoc.data());

            const memberUIDs = serverData.members || [];
            if (memberUIDs.length > 0) {
                const userDocs = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', memberUIDs).get();
                activeServerUserProfiles = {};
                userDocs.docs.forEach((d: any) => {
                    const mData = activeServerMembers[d.id] || {};
                    activeServerUserProfiles[d.id] = { id: d.id, ...d.data(), ...mData };
                });
                renderUsers(activeServerUserProfiles);
            }
        }
    });

    channelUnsubscribe = serverRef.collection('channels').orderBy('name').onSnapshot((snapshot: any) => {
        const channels = snapshot.docs.map((d: any) => ({ id: d.id, ...d.data() }));
        renderChannels(activeServerData, channels);
        if (!activeChannelId && channels.length > 0) selectChannel(channels[0].id);
    });
};

const selectChannel = (channelId: string) => {
    activeChannelId = channelId;
    if (messageUnsubscribe) messageUnsubscribe();

    lastSeenTimestamps[channelId] = Date.now();
    localStorage.setItem('lastSeenTimestamps', JSON.stringify(lastSeenTimestamps));
    unreadChannels.delete(channelId);

    setDisplay('placeholder-view', 'none');
    setDisplay('chat-view', 'flex');

    if (!db || !activeServerId) return;
    const channelRef = db.collection('servers').doc(activeServerId).collection('channels').doc(channelId);

    channelRef.get().then((doc: any) => {
        if (doc.exists) {
            const data = doc.data();
            const header = getEl('chat-header');
            if (header) {
                header.innerHTML = `<svg class="w-6 h-6 text-gray-500 mr-2" fill="currentColor" viewBox="0 0 24 24"><path d="M10 9h4V7h-4v2zm-2 4h4v-2H8v2zm10-4v2h-4V9h4zm2-2h-4V5h4v2zm-4 8h4v-2h-4v2zm-2-4h-4v2h4v-2zm-2 4h2v2h-2v-2zm-6-4H4v2h2v-2zM6 7H4v2h2V7zm10 10v-2h-4v2h4zm-6 0v-2H8v2h2z"></path></svg><h2 class="font-semibold text-lg text-white">${data.name}</h2>`;
            }
        }
    });

    messageUnsubscribe = channelRef.collection('messages').orderBy('timestamp', 'asc').onSnapshot((snap: any) => {
        const messages = snap.docs.map((d: any) => ({ id: d.id, ...d.data() }));
        renderMessages(messages);
    });
};

const selectDmChannel = async (friend: any) => {
    const getDmChannelId = (fId: string) => [currentUser.uid, fId].sort().join('_');
    const dmId = getDmChannelId(friend.id);
