// =================================================================================
// DOM Helpers with Robust Null Safety
// =================================================================================
const getEl = (id: string) => document.getElementById(id);

const addClass = (id: string, className: string) => {
    const el = getEl(id);
    if (el) el.classList.add(className);
};

const removeClass = (id: string, className: string) => {
    const el = getEl(id);
    if (el) el.classList.remove(className);
};

const toggleClass = (id: string, className: string, force?: boolean) => {
    const el = getEl(id);
    if (el) el.classList.toggle(className, force);
};

const setDisplay = (id: string, style: string) => {
    const el = getEl(id);
    if (el) el.style.display = style;
};

const setText = (id: string, text: string) => {
    const el = getEl(id);
    if (el) el.textContent = text;
};

// =================================================================================
// Constants & Utils
// =================================================================================
const DEFAULT_AVATAR_SVG = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ccircle cx='50' cy='50' r='50' fill='%2372767d'/%3E%3C/svg%3E";

const isValidHttpUrl = (string: string) => {
    if (!string) return false;
    try {
        const newUrl = new URL(string);
        return newUrl.protocol === 'http:' || newUrl.protocol === 'https:';
    } catch (_) { return false; }
};

const escapeHTML = (str: string) => {
    if (!str) return '';
    return str.replace(/[&<>"']/g, (m) => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[m] || m));
};

// =================================================================================
// App State
// =================================================================================
let currentUser: any = null;
let activeView: 'servers' | 'home' = 'servers';
let activeServerId: string | null = null;
let activeChannelId: string | null = null;
let activeServerData: any = null;
let activeServerUserProfiles: any = {};
let lastSeenTimestamps: any = {};

// Unsubscribe listeners
let messageUnsubscribe = () => {};
let channelUnsubscribe = () => {};
let usersUnsubscribe = () => {};
let serversUnsubscribe = () => {};
let friendsUnsubscribe = () => {};
let invitationsUnsubscribe = () => {};

// =================================================================================
