    if (!db) return;
    messageUnsubscribe = db.collection('dms').doc(dmId).collection('messages').orderBy('timestamp', 'asc').limitToLast(50).onSnapshot((snap: any) => {
        const messages = snap.docs.map((d: any) => ({ id: d.id, ...d.data() }));
        renderMessages(messages);
    });
};

