const loadServers = () => {
    if (serversUnsubscribe) serversUnsubscribe();
    if (!currentUser || !db) return;
    serversUnsubscribe = db.collection('servers')
        .where('members', 'array-contains', currentUser.uid)
        .onSnapshot((snapshot: any) => {
            const servers = snapshot.docs.map((d: any) => ({ id: d.id, ...d.data() }));
            renderServers(servers);
        });
};

const loadFriends = () => {
    if (friendsUnsubscribe) friendsUnsubscribe();
    if (!currentUser || !db) return;
    friendsUnsubscribe = db.collection('users').doc(currentUser.uid).onSnapshot(async (doc: any) => {
        if (doc.exists) {
            const data = doc.data();
            const fIds = data.friends || [];
            if (fIds.length > 0) {
                const fDocs = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', fIds).get();
                const friends = fDocs.docs.map((d: any) => ({ id: d.id, ...d.data() }));
                renderFriends(friends);
            } else {
                renderFriends([]);
            }
        }
    });
};

const setupInvitationsListener = () => {
    if (invitationsUnsubscribe) invitationsUnsubscribe();
    if (!currentUser || !db) return;
    invitationsUnsubscribe = db.collection('invitations')
        .where('toId', '==', currentUser.uid)
        .where('status', '==', 'pending')
        .onSnapshot((snapshot: any) => {
            const badge = getEl('pending-invites-badge');
            if (badge) {
                const count = snapshot.docs.length;
                badge.textContent = count.toString();
                badge.classList.toggle('hidden', count === 0);
            }
        });
};

// =================================================================================
// Handlers
// =================================================================================

const handleSendMessage = async (e: Event) => {
    e.preventDefault();
    const input = getEl('message-input') as HTMLInputElement;
    const text = input ? input.value.trim() : "";
    if (!text || !currentUser || !db || !activeChannelId) return;

    if (input) input.value = '';
    const msg = {
        text,
        timestamp: firebase.firestore.FieldValue.serverTimestamp(),
        user: { uid: currentUser.uid, displayName: currentUser.displayName, photoURL: currentUser.photoURL }
    };

    try {
        if (activeView === 'servers' && activeServerId) {
            await db.collection('servers').doc(activeServerId).collection('channels').doc(activeChannelId).collection('messages').add(msg);
        } else {
            await db.collection('dms').doc(activeChannelId).collection('messages').add(msg);
        }
    } catch (err) {
        console.error("Message send failed:", err);
    }
};

const handleAddFriend = async (e: Event) => {
    e.preventDefault();
    const input = getEl('add-friend-input') as HTMLInputElement;
    const enteredId = input ? input.value.trim() : "";
    if (!enteredId || !currentUser || !db) return;

    try {
        const userDoc = await db.collection('users').doc(enteredId).get();
        if (!userDoc.exists) {
            setText('add-friend-status', 'User ID not found.');
            addClass('add-friend-status', 'text-red-400');
            return;
        }
        if (enteredId === currentUser.uid) {
            setText('add-friend-status', "Can't add yourself.");
            addClass('add-friend-status', 'text-red-400');
            return;
        }

        await db.collection('invitations').add({
            fromId: currentUser.uid,
            fromName: currentUser.displayName,
            toId: enteredId,
            type: 'friend',
            status: 'pending',
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });

        setText('add-friend-status', 'Invite sent!');
        removeClass('add-friend-status', 'text-red-400');
        addClass('add-friend-status', 'text-green-400');
        if (input) input.value = '';
    } catch (err) {
        console.error(err);
    }
};

const handleCreateServer = async (e: Event) => {
    e.preventDefault();
    const input = getEl('server-name-input') as HTMLInputElement;
    const name = input ? input.value.trim() : "";
    if (!name || !currentUser || !db) return;

    try {
        const serverRef = await db.collection('servers').add({
            name,
            owner: currentUser.uid,
            members: [currentUser.uid],
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        await serverRef.collection('channels').add({ name: 'general', createdAt: firebase.firestore.FieldValue.serverTimestamp() });
        setDisplay('add-server-modal', 'none');
        if (input) input.value = '';
    } catch (err) {
        console.error("Server creation failed:", err);
    }
};

const handleUpdateProfile = async (e: Event) => {
    e.preventDefault();
    const nameInput = getEl('profile-username-input') as HTMLInputElement;
    const avatarInput = getEl('profile-avatar-input') as HTMLInputElement;
    if (!currentUser || !db) return;

    const newName = nameInput ? nameInput.value.trim() : currentUser.displayName;
    const newAvatar = avatarInput ? avatarInput.value.trim() : currentUser.photoURL;

    try {
        await db.collection('users').doc(currentUser.uid).update({
            displayName: newName,
            photoURL: newAvatar
        });
        currentUser.displayName = newName;
        currentUser.photoURL = newAvatar;
        renderUserInfo();
        setDisplay('my-profile-modal', 'none');
    } catch (err) {
        console.error("Profile update failed:", err);
    }
};

const handleServerInvite = async (e: Event) => {
    e.preventDefault();
    const input = getEl('user-id-input') as HTMLInputElement;
    const toId = input ? input.value.trim() : "";
    if (!toId || !activeServerId || !db) return;

    try {
        const userDoc = await db.collection('users').doc(toId).get();
        if (!userDoc.exists) {
            setText('invite-status-message', 'User ID not found.');
            addClass('invite-status-message', 'text-red-400');
            return;
        }

        await db.collection('invitations').add({
            fromId: currentUser.uid,
            toId,
            serverId: activeServerId,
            serverName: activeServerData?.name || 'Unknown Server',
            type: 'server',
            status: 'pending',
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });

        setText('invite-status-message', 'Invitation sent!');
        removeClass('invite-status-message', 'text-red-400');
        addClass('invite-status-message', 'text-green-400');
        if (input) input.value = '';
    } catch (err) {
        console.error("Invite failed:", err);
    }
};

// =================================================================================
// Auth Initialization
// =================================================================================
if (auth) {
    auth.onAuthStateChanged(async (user: any) => {
        if (user) {
            try {
                addClass('app-error-overlay', 'hidden');
                const userDocRef = db!.collection('users').doc(user.uid);
                const userDoc = await userDocRef.get();

                if (!userDoc.exists) {
                    const displayName = user.displayName || user.email.split('@')[0];
                    const photoURL = user.photoURL || `https://i.pravatar.cc/64?u=${user.uid}`;
                    await userDocRef.set({ displayName, photoURL, status: 'online', friends: [], blockedUsers: [] });
                    currentUser = { uid: user.uid, displayName, photoURL, email: user.email };
                } else {
                    const userData = userDoc.data();
                    await userDocRef.update({ status: 'online' });
                    currentUser = { uid: user.uid, displayName: userData.displayName, photoURL: userData.photoURL, email: user.email };
                }

                setDisplay('login-view', 'none');
                setDisplay('app-view', 'flex');
                renderUserInfo();
                loadServers();
                loadFriends();
                setupPresence();
                setupInvitationsListener();
                selectHome();
            } catch (error) {
                console.error(error);
                removeClass('app-error-overlay', 'hidden');
                setText('app-error-message', "Authentication failed. Check your connection.");
            }
        } else {
            currentUser = null;
            setDisplay('login-view', 'flex');
            setDisplay('app-view', 'none');
        }
    });
}

// =================================================================================
// Event Listeners (Safe Assignment)
// =================================================================================
const safeBind = (id: string, event: string, handler: (e: any) => void) => {
    const el = getEl(id);
    if (el) el.addEventListener(event, handler);
};

safeBind('login-button', 'click', () => auth?.signInWithPopup(provider));
safeBind('message-form', 'submit', handleSendMessage);
safeBind('add-friend-form', 'submit', handleAddFriend);
safeBind('add-server-form', 'submit', handleCreateServer);
safeBind('profile-form', 'submit', handleUpdateProfile);
