safeBind('close-my-profile-modal', 'click', () => setDisplay('my-profile-modal', 'none'));
safeBind('toggle-home-panel-button', 'click', () => toggleClass('home-view', 'hidden'));

safeBind('show-signin-link', 'click', (e) => { e.preventDefault(); addClass('signup-form', 'hidden'); removeClass('signin-form', 'hidden'); });
safeBind('show-signup-link', 'click', (e) => { e.preventDefault(); addClass('signin-form', 'hidden'); removeClass('signup-form', 'hidden'); });

document.querySelectorAll('.user-info-panel').forEach(p => {
    (p as HTMLElement).onclick = () => {
        setText('user-id-display', currentUser?.uid || '');
        const nameInput = getEl('profile-username-input') as HTMLInputElement;
        const avatarInput = getEl('profile-avatar-input') as HTMLInputElement;
        if (nameInput) nameInput.value = currentUser?.displayName || '';
