// =================================================================================
// DOM Helpers
// =================================================================================
const getEl = (id: string) => document.getElementById(id);
const setDisplay = (id: string, style: string) => {
    const el = getEl(id);
    if (el) el.style.display = style;
};
const addClass = (id: string, className: string) => {
    const el = getEl(id);
    if (el) el.classList.add(className);
};
const removeClass = (id: string, className: string) => {
    const el = getEl(id);
    if (el) el.classList.remove(className);
};
const setText = (id: string, text: string) => {
    const el = getEl(id);
    if (el) el.textContent = text;
};

// =================================================================================
// Constants & Utils
// =================================================================================
const DEFAULT_AVATAR = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ccircle cx='50' cy='50' r='50' fill='%2372767d'/%3E%3C/svg%3E";

const isValidHttpUrl = (string: string) => {
    if (!string) return false;
    try {
        const newUrl = new URL(string);
        return newUrl.protocol === 'http:' || newUrl.protocol === 'https:';
    } catch (_) { return false; }
};

const escapeHTML = (str: string) => {
    if (!str) return '';
    return str.replace(/[&<>"']/g, (m) => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[m] || m));
};

// =================================================================================
// App State
// =================================================================================
let currentUser: any = null;
let activeView: 'servers' | 'home' = 'servers';
let activeServerId: string | null = null;
let activeChannelId: string | null = null;
let activeServerData: any = null;

// Listeners
let messageUnsubscribe = () => {};
let channelUnsubscribe = () => {};
let usersUnsubscribe = () => {};
let serversUnsubscribe = () => {};
let friendsUnsubscribe = () => {};
let invitationsUnsubscribe = () => {};

// =================================================================================
// Navigation & Selection
// =================================================================================

const selectHome = async () => {
    activeView = 'home';
    activeServerId = null;
    activeChannelId = null;
    activeServerData = null;

    if (messageUnsubscribe) messageUnsubscribe();
    if (channelUnsubscribe) channelUnsubscribe();
    if (usersUnsubscribe) usersUnsubscribe();

    setDisplay('home-view', 'flex');
    setDisplay('channel-list-panel', 'none');
    setDisplay('chat-view', 'none');
    setDisplay('user-list-aside', 'none');
    setDisplay('placeholder-view', 'flex');

    loadServers();
    loadFriends();
};

const selectServer = async (serverId: string) => {
    if (activeServerId === serverId && activeView === 'servers') return;
    activeView = 'servers';
    activeServerId = serverId;
    activeChannelId = null;

    if (channelUnsubscribe) channelUnsubscribe();
    if (usersUnsubscribe) usersUnsubscribe();
    if (messageUnsubscribe) messageUnsubscribe();

    setDisplay('home-view', 'none');
    setDisplay('channel-list-panel', 'flex');
    setDisplay('user-list-aside', 'block');
    setDisplay('chat-view', 'none');
    setDisplay('placeholder-view', 'flex');

    if (!db) return;
    const serverRef = db.collection('servers').doc(serverId);

    usersUnsubscribe = serverRef.onSnapshot(async (doc: any) => {
        if (doc.exists) {
            const data = doc.data();
            activeServerData = data;
            const members = data.members || [];
            if (members.length > 0) {
                const userDocs = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', members.slice(0, 10)).get();
                const profiles = {};
                userDocs.docs.forEach((d: any) => { profiles[d.id] = { id: d.id, ...d.data() }; });
                renderUsers(profiles);
            }
        }
    });

    channelUnsubscribe = serverRef.collection('channels').orderBy('name').onSnapshot((snap: any) => {
        const channels = snap.docs.map((d: any) => ({ id: d.id, ...d.data() }));
        renderChannels(activeServerData, channels);
        if (!activeChannelId && channels.length > 0) selectChannel(channels[0].id);
    });
};

const selectChannel = (channelId: string) => {
    activeChannelId = channelId;
    if (messageUnsubscribe) messageUnsubscribe();

    setDisplay('placeholder-view', 'none');
    setDisplay('chat-view', 'flex');

    if (!db || !activeServerId) return;
    const channelRef = db.collection('servers').doc(activeServerId).collection('channels').doc(channelId);

    channelRef.get().then((doc: any) => {
        if (doc.exists) {
            const data = doc.data();
            const header = getEl('chat-header');
            if (header) header.innerHTML = `<h2 class="font-semibold text-lg text-white"># ${data.name}</h2>`;
        }
    });

    messageUnsubscribe = channelRef.collection('messages').orderBy('timestamp', 'asc').limitToLast(50).onSnapshot((snap: any) => {
        renderMessages(snap.docs.map((d: any) => ({ id: d.id, ...d.data() })));
    });
};

const selectDmChannel = async (friend: any) => {
    const dmId = [currentUser.uid, friend.id].sort().join('_');
    activeChannelId = dmId;
    if (messageUnsubscribe) messageUnsubscribe();

    setDisplay('placeholder-view', 'none');
    setDisplay('chat-view', 'flex');
    setDisplay('user-list-aside', 'none');

    const header = getEl('chat-header');
    if (header) header.innerHTML = `<h2 class="font-semibold text-lg text-white">@ ${friend.displayName}</h2>`;

    if (!db) return;
    messageUnsubscribe = db.collection('dms').doc(dmId).collection('messages').orderBy('timestamp', 'asc').limitToLast(50).onSnapshot((snap: any) => {
        renderMessages(snap.docs.map((d: any) => ({ id: d.id, ...d.data() })));
    });
};

// =================================================================================
// Renderers
// =================================================================================

const renderUserInfo = () => {
    if (!currentUser) return;
    const avatar = isValidHttpUrl(currentUser.photoURL) ? currentUser.photoURL : DEFAULT_AVATAR;
    const html = `
        <img src="${avatar}" class="w-8 h-8 rounded-full object-cover mr-2"/>
        <div class="truncate">
            <p class="text-xs font-bold text-white truncate">${currentUser.displayName}</p>
            <p class="text-[10px] text-gray-400">#${currentUser.uid.slice(0,4)}</p>
        </div>
    `;
    document.querySelectorAll('.user-info-panel').forEach(p => p.innerHTML = html);
};

const renderServers = (servers: any[]) => {
    const container = getEl('server-list-container');
    if (!container) return;
    container.innerHTML = '';

    // Home button
    const homeBtn = document.createElement('button');
    homeBtn.className = `w-12 h-12 mb-2 rounded-3xl flex items-center justify-center transition-all ${activeView === 'home' ? 'bg-blue-500 rounded-2xl' : 'bg-gray-700 hover:bg-blue-500 hover:rounded-2xl'}`;
    homeBtn.innerHTML = `<svg class="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20"><path d="M10.707 2.293a1 1 0 00-1.414 0l-7 7a1 1 0 001.414 1.414L4 10.414V17a1 1 0 001 1h2a1 1 0 001-1v-2a1 1 0 011-1h2a1 1 0 011 1v2a1 1 0 001 1h2a1 1 0 001-1v-6.586l.293.293a1 1 0 001.414-1.414l-7-7z"></path></svg>`;
    homeBtn.onclick = selectHome;
    container.appendChild(homeBtn);

    servers.forEach(s => {
        const btn = document.createElement('button');
        const isActive = activeServerId === s.id;
        btn.className = `w-12 h-12 mb-2 rounded-3xl overflow-hidden transition-all ${isActive ? 'rounded-2xl ring-2 ring-white' : 'hover:rounded-2xl'}`;
        const icon = isValidHttpUrl(s.iconUrl) ? s.iconUrl : DEFAULT_AVATAR;
        btn.innerHTML = `<img src="${icon}" class="w-full h-full object-cover" title="${s.name}"/>`;
        btn.onclick = () => selectServer(s.id);
        container.appendChild(btn);
    });

    const addBtn = document.createElement('button');
    addBtn.className = "w-12 h-12 bg-gray-700 rounded-3xl flex items-center justify-center hover:bg-green-500 hover:rounded-2xl transition-all";
    addBtn.innerHTML = `<span class="text-2xl text-green-500 hover:text-white">+</span>`;
    addBtn.onclick = () => setDisplay('add-server-modal', 'flex');
    container.appendChild(addBtn);
};

const renderChannels = (server: any, channels: any[]) => {
    setText('server-name-text', server?.name || 'Server');
    const list = getEl('channel-list');
    if (!list) return;
    list.innerHTML = `<h2 class="text-xs font-bold text-gray-500 uppercase px-2 mb-2">Channels</h2>`;
    channels.forEach(ch => {
        const btn = document.createElement('button');
        btn.className = `w-full text-left px-2 py-1 rounded text-sm ${activeChannelId === ch.id ? 'bg-gray-700 text-white' : 'text-gray-400 hover:bg-gray-700/50 hover:text-gray-200'}`;
        btn.textContent = `# ${ch.name}`;
        btn.onclick = () => selectChannel(ch.id);
        list.appendChild(btn);
    });
};

const renderFriends = (friends: any[]) => {
    const list = getEl('friend-list');
    if (!list) return;
    list.innerHTML = `<h2 class="text-xs font-bold text-gray-500 uppercase px-2 mb-2">Direct Messages</h2>`;
    friends.forEach(f => {
        const wrap = document.createElement('div');
        wrap.className = "flex items-center px-2 py-1.5 rounded-md hover:bg-gray-700/50 cursor-pointer";
        wrap.innerHTML = `<span class="text-sm font-medium text-gray-400">@ ${f.displayName}</span>`;
        wrap.onclick = () => selectDmChannel(f);
        list.appendChild(wrap);
    });
};

const renderMessages = (messages: any[]) => {
    const list = getEl('message-list');
    if (!list) return;
    list.innerHTML = '';
    messages.forEach(m => {
        const div = document.createElement('div');
        div.className = "flex p-2 hover:bg-gray-800/20";
        const avatar = isValidHttpUrl(m.user?.photoURL) ? m.user.photoURL : DEFAULT_AVATAR;
        div.innerHTML = `
            <img src="${avatar}" class="w-10 h-10 rounded-full mr-3 object-cover" />
            <div>
                <div class="flex items-center">
                    <span class="font-bold text-white text-sm mr-2">${m.user?.displayName || 'Unknown'}</span>
                    <span class="text-[10px] text-gray-500">${m.timestamp ? new Date(m.timestamp.toDate()).toLocaleTimeString() : '...'}</span>
                </div>
                <div class="text-gray-300 text-sm">${escapeHTML(m.text || '')}</div>
            </div>
        `;
        list.appendChild(div);
    });
    list.scrollTop = list.scrollHeight;
};

const renderUsers = (users: any) => {
    const list = getEl('user-list-aside');
    if (!list) return;
    list.innerHTML = `<h3 class="text-xs font-bold uppercase text-gray-500 px-2 mb-2">Members</h3>`;
    Object.values(users).forEach((u: any) => {
        const wrap = document.createElement('div');
        wrap.className = "flex items-center p-2 text-sm text-gray-400";
        wrap.innerHTML = `<span class="mr-2 w-2 h-2 rounded-full ${u.status === 'online' ? 'bg-green-500' : 'bg-gray-500'}"></span>${u.displayName}`;
        list.appendChild(wrap);
    });
};

// =================================================================================
// Data Loading
// =================================================================================

const loadServers = () => {
    if (serversUnsubscribe) serversUnsubscribe();
    if (!currentUser || !db) return;
    serversUnsubscribe = db.collection('servers').where('members', 'array-contains', currentUser.uid).onSnapshot((snap: any) => {
        renderServers(snap.docs.map((d: any) => ({ id: d.id, ...d.data() })));
    });
};

const loadFriends = () => {
    if (friendsUnsubscribe) friendsUnsubscribe();
    if (!currentUser || !db) return;
    friendsUnsubscribe = db.collection('users').doc(currentUser.uid).onSnapshot(async (doc: any) => {
        if (doc.exists) {
            const fIds = doc.data().friends || [];
            if (fIds.length > 0) {
                const fDocs = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', fIds.slice(0,10)).get();
                renderFriends(fDocs.docs.map((d: any) => ({ id: d.id, ...d.data() })));
            } else { renderFriends([]); }
        }
    });
};

// =================================================================================
// Handlers
// =================================================================================

const handleSendMessage = async (e: Event) => {
    e.preventDefault();
    const input = getEl('message-input') as HTMLInputElement;
    const text = input ? input.value.trim() : "";
    if (!text || !currentUser || !db || !activeChannelId) return;
    input.value = '';
    const msg = { text, timestamp: firebase.firestore.FieldValue.serverTimestamp(), user: { uid: currentUser.uid, displayName: currentUser.displayName, photoURL: currentUser.photoURL } };
    if (activeView === 'servers' && activeServerId) {
        await db.collection('servers').doc(activeServerId).collection('channels').doc(activeChannelId).collection('messages').add(msg);
    } else {
        await db.collection('dms').doc(activeChannelId).collection('messages').add(msg);
    }
};

const showError = (msg: string) => {
    const err = getEl('login-error-container');
    if (err) {
        err.textContent = msg;
        err.style.display = 'block';
    }
};

const setupUserDoc = async (user: any) => {
    if (!db) return;
    const ref = db.collection('users').doc(user.uid);
    const doc = await ref.get();
    if (!doc.exists) {
        const displayName = user.displayName || (user.isAnonymous ? "Guest_" + user.uid.slice(0, 4) : user.email.split('@')[0]);
        const photoURL = user.photoURL || `https://i.pravatar.cc/64?u=${user.uid}`;
        await ref.set({ displayName, photoURL, status: 'online', friends: [] });
    } else {
        await ref.update({ status: 'online' });
    }
};

// =================================================================================
// Auth
// =================================================================================

if (auth) {
    auth.onAuthStateChanged(async (user: any) => {
        if (user) {
            currentUser = user;
            await setupUserDoc(user);
            setDisplay('login-view', 'none');
            setDisplay('app-view', 'flex');
            renderUserInfo();
            selectHome();
        } else {
            currentUser = null;
            setDisplay('login-view', 'flex');
            setDisplay('app-view', 'none');
        }
    });
}

