    auth?.signInWithPopup(provider).catch(err => {
        showError(`Google Login failed: ${err.code}. Popups might be blocked.`);
    });
});

safeBind('signin-form', 'submit', () => {
    const email = (getEl('signin-email') as HTMLInputElement).value;
    const pass = (getEl('signin-password') as HTMLInputElement).value;
    auth?.signInWithEmailAndPassword(email, pass).catch(err => showError(err.message));
});

safeBind('signup-form', 'submit', () => {
    const email = (getEl('signup-email') as HTMLInputElement).value;
    const pass = (getEl('signup-password') as HTMLInputElement).value;
    auth?.createUserWithEmailAndPassword(email, pass).catch(err => showError(err.message));
});

safeBind('message-form', 'submit', handleSendMessage);

