const selectServer = async (serverId) => {
    if (activeServerId === serverId && activeView === 'servers') return;
    await hangUp();
    activeView = 'servers';
    activeServerId = serverId;
    activeChannelId = null;

    if (channelUnsubscribe) channelUnsubscribe();
    if (usersUnsubscribe) usersUnsubscribe();
    if (messageUnsubscribe) messageUnsubscribe();

    document.getElementById('home-view').style.display = 'none';
    document.getElementById('channel-list-panel').style.display = 'flex';
    document.getElementById('user-list-aside').style.display = 'block';

    const serverRef = db.collection('servers').doc(serverId);
    usersUnsubscribe = serverRef.onSnapshot(async doc => {
        if (doc.exists) {
            activeServerData = doc.data();
            activeServerRoles = activeServerData.roles || {};
            activeServerRoleOrder = activeServerData.roleOrder || Object.keys(activeServerRoles);

            const membersSnap = await serverRef.collection('members').get();
            activeServerMembers = {};
            membersSnap.forEach(m => activeServerMembers[m.id] = m.data());

            const uSnap = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', activeServerData.members || []).get();
            activeServerUserProfiles = {};
            uSnap.docs.forEach(d => activeServerUserProfiles[d.id] = { id: d.id, ...d.data(), ...activeServerMembers[d.id] });
            renderUsers(activeServerUserProfiles);
