// Server Call / Voice Channel Logic
// =================================================================================

const joinServerVoice = async (channelId, channelName) => {
    if (activeCallData) await hangUp();

    try {
        localStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
        document.getElementById('local-video').srcObject = localStream;
    } catch (e) { return alert("Mic/Camera access required."); }

    const callRef = db.collection('servers').doc(activeServerId).collection('channels').doc(channelId).collection('activeCall').doc('session');
    const callDoc = await callRef.get();

    activeCallData = { id: 'session', serverId: activeServerId, channelId };
    showCallUI('connected', { displayName: `# ${channelName}` });

    peerConnection = new RTCPeerConnection(iceServers);
    localStream.getTracks().forEach(t => peerConnection.addTrack(t, localStream));

    peerConnection.onicecandidate = e => e.candidate && callRef.collection('candidates').add(e.candidate.toJSON());
    peerConnection.ontrack = e => {
        remoteStream.addTrack(e.track);
        document.getElementById('remote-video').srcObject = remoteStream;
    };

    if (!callDoc.exists || callDoc.data().status === 'ended') {
        // We are the host
        const offer = await peerConnection.createOffer();
        await peerConnection.setLocalDescription(offer);
        await callRef.set({ offer: { sdp: offer.sdp, type: offer.type }, status: 'live', hostId: currentUser.uid });

        currentCallUnsubscribe = callRef.onSnapshot(async snap => {
            const data = snap.data();
            if (data?.answer && !peerConnection.currentRemoteDescription) {
                await peerConnection.setRemoteDescription(new RTCSessionDescription(data.answer));
            }
        });
    } else {
        // Someone is already here, we are the joiner
        const data = callDoc.data();
        await peerConnection.setRemoteDescription(new RTCSessionDescription(data.offer));
        const answer = await peerConnection.createAnswer();
