const hangUp = async () => {
    if (peerConnection) {
        peerConnection.close();
        peerConnection = null;
    }
    if (localStream) {
        localStream.getTracks().forEach(t => t.stop());
        localStream = null;
    }
    setDisplay('video-call-view', 'none');
    const rv = getEl('remote-video') as HTMLVideoElement;
    if (rv) rv.srcObject = null;
    const lv = getEl('local-video') as HTMLVideoElement;
    if (lv) lv.srcObject = null;

    if (currentCallUnsubscribe) currentCallUnsubscribe();
    if (calleeCandidatesUnsubscribe) calleeCandidatesUnsubscribe();

    remoteStream = new MediaStream();
};

const joinServerVoice = async (channelId: string, channelName: string) => {
    await hangUp();
    setDisplay('video-call-view', 'flex');
    const statusEl = getEl('remote-username');
    if (statusEl) statusEl.textContent = `Connecting to #${channelName}...`;

    try {
        localStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
        const lv = getEl('local-video') as HTMLVideoElement;
        if (lv) lv.srcObject = localStream;
    } catch (e) {
        console.error(e);
        alert("Camera and Microphone access are required for voice channels.");
        return;
    }

    if (!db || !activeServerId) return;
    const callRef = db.collection('servers').doc(activeServerId).collection('channels').doc(channelId).collection('activeCall').doc('session');
    const callDoc = await callRef.get();

    peerConnection = new RTCPeerConnection(iceServers);
    localStream.getTracks().forEach(t => peerConnection!.addTrack(t, localStream!));

    peerConnection.onicecandidate = e => {
        if (e.candidate) callRef.collection('candidates').add(e.candidate.toJSON());
    };

    peerConnection.ontrack = e => {
        e.streams[0].getTracks().forEach(track => remoteStream.addTrack(track));
        const rv = getEl('remote-video') as HTMLVideoElement;
        if (rv) rv.srcObject = remoteStream;
        if (statusEl) statusEl.textContent = channelName;
    };

    if (!callDoc.exists || callDoc.data().status === 'ended') {
        const offer = await peerConnection.createOffer();
        await peerConnection.setLocalDescription(offer);
        await callRef.set({ offer: { sdp: offer.sdp, type: offer.type }, status: 'live', hostId: currentUser.uid });

        currentCallUnsubscribe = callRef.onSnapshot(async snap => {
            const data = snap.data();
            if (data?.answer && peerConnection && !peerConnection.currentRemoteDescription) {
                await peerConnection.setRemoteDescription(new RTCSessionDescription(data.answer));
            }
        });
    } else {
        const data = callDoc.data();
        await peerConnection.setRemoteDescription(new RTCSessionDescription(data.offer));
        const answer = await peerConnection.createAnswer();
        await peerConnection.setLocalDescription(answer);
        await callRef.update({ answer: { sdp: answer.sdp, type: answer.type } });
    }

    calleeCandidatesUnsubscribe = callRef.collection('candidates').onSnapshot(snap => {
        snap.docChanges().forEach(change => {
            if (change.type === 'added' && peerConnection) {
                const cand = new RTCIceCandidate(change.doc.data());
                peerConnection.addIceCandidate(cand).catch(e => console.error("ICE error", e));
            }
        });
    });
};

const selectChannel = async (channelId: string) => {
    activeChannelId = channelId;
    if (messageUnsubscribe) messageUnsubscribe();

    if (!db || !activeServerId) return;
    const chDoc = await db.collection('servers').doc(activeServerId).collection('channels').doc(channelId).get();
    const chData = chDoc.data();
    activeChannelType = chData.type || 'text';

    setDisplay('placeholder-view', 'none');

    if (activeChannelType === 'voice') {
