const handleCreateServer = async (e: Event) => {
    e.preventDefault();
    const input = getEl('server-name-input') as HTMLInputElement;
    const name = input.value.trim();
    if (name && db && currentUser) {
        const ref = await db.collection('servers').add({ 
            name, 
            owner: currentUser.uid, 
            members: [currentUser.uid], 
            createdAt: firebase.firestore.FieldValue.serverTimestamp() 
        });
        await ref.collection('channels').add({ name: 'general', type: 'text' });
        input.value = '';
