const selectHome = async () => {
    await hangUp();
    activeView = 'home';
    activeServerId = null;
    activeChannelId = null;
    setDisplay('home-view', 'flex');
    setDisplay('channel-list-panel', 'none');
    setDisplay('chat-view', 'none');
    setDisplay('placeholder-view', 'flex');
    loadFriends();
    loadServers();
