const loadServers = () => {
    if (!currentUser) return;
    if (serversUnsubscribe) serversUnsubscribe();
    serversUnsubscribe = db.collection('servers').where('members', 'array-contains', currentUser.uid).onSnapshot((snap: any) => {
        const servers = snap.docs.map((d: any) => ({ id: d.id, ...d.data() }));
        renderServers(servers);
    });
};

auth.onAuthStateChanged(async (user: any) => {
    if (user) {
        currentUser = user;
        const uref = db.collection('users').doc(user.uid);
        const udoc = await uref.get();
        if (!udoc.exists) {
            const dn = user.displayName || user.email.split('@')[0];
            const p = user.photoURL || DEFAULT_AVATAR_SVG;
            await uref.set({ displayName: dn, photoURL: p, status: 'online', friends: [] });
        } else {
            await uref.update({ status: 'online' });
        }
        setDisplay('login-view', 'none');
        setDisplay('app-view', 'flex');
        renderUserInfo();
        selectHome();
    } else {
        currentUser = null;
        setDisplay('login-view', 'flex');
        setDisplay('app-view', 'none');
    }
});

document.addEventListener('DOMContentLoaded', () => {
    const loginBtn = getEl('login-button');
    if (loginBtn) loginBtn.onclick = () => auth.signInWithPopup(provider);

    const signupForm = getEl('signup-form');
    if (signupForm) signupForm.onsubmit = async (e) => {
        e.preventDefault();
        const email = (getEl('signup-email') as HTMLInputElement).value;
        const pass = (getEl('signup-password') as HTMLInputElement).value;
        try { await auth.createUserWithEmailAndPassword(email, pass); } catch(err: any) { alert(err.message); }
    };

    const signinForm = getEl('signin-form');
    if (signinForm) signinForm.onsubmit = async (e) => {
        e.preventDefault();
        const email = (getEl('signin-email') as HTMLInputElement).value;
        const pass = (getEl('signin-password') as HTMLInputElement).value;
        try { await auth.signInWithEmailAndPassword(email, pass); } catch(err: any) { alert(err.message); }
    };

    const showSignIn = getEl('show-signin-link');
    if (showSignIn) showSignIn.onclick = (e) => { e.preventDefault(); setDisplay('signup-form', 'none'); setDisplay('signin-form', 'block'); };

    const showSignUp = getEl('show-signup-link');
    if (showSignUp) showSignUp.onclick = (e) => { e.preventDefault(); setDisplay('signin-form', 'none'); setDisplay('signup-form', 'block'); };

    const msgForm = getEl('message-form');
    if (msgForm) msgForm.onsubmit = handleSendMessage;

    const createRoomForm = getEl('add-server-form');
    if (createRoomForm) createRoomForm.onsubmit = handleCreateRoom;

    const joinRoomForm = getEl('join-server-form');
    if (joinRoomForm) joinRoomForm.onsubmit = handleJoinRoom;

    const cancelModal = getEl('cancel-add-server');
    if (cancelModal) cancelModal.onclick = () => setDisplay('add-server-modal', 'none');

    const serverOpsBtn = getEl('server-options-button');
    if (serverOpsBtn) serverOpsBtn.onclick = (e) => { e.stopPropagation(); getEl('server-options-dropdown')?.classList.toggle('hidden'); };

    const leaveBtn = getEl('leave-server-button');
    if (leaveBtn) leaveBtn.onclick = handleLeaveRoom;

    const messageInput = getEl('message-input') as HTMLInputElement;
    if (messageInput) {
        messageInput.oninput = (e: any) => {
            const charCounter = getEl('char-counter');
            if (charCounter) charCounter.textContent = `${e.target.value.length} / 500`;
        };
    }

    const toggleHomeBtn = getEl('toggle-home-panel-button');
    if (toggleHomeBtn) {
        toggleHomeBtn.innerHTML = ICONS.COLLAPSE;
        toggleHomeBtn.onclick = () => {
            const hv = getEl('home-view');
            if (!hv) return;
            const isMin = hv.classList.contains('w-16');
            hv.classList.toggle('w-60', isMin);
            hv.classList.toggle('w-16', !isMin);
            const title = getEl('home-view-title');
            if (title) title.classList.toggle('hidden', !isMin);
            const content = getEl('home-view-content');
            if (content) content.classList.toggle('hidden', !isMin);
            toggleHomeBtn.innerHTML = isMin ? ICONS.COLLAPSE : ICONS.EXPAND;
        };
    }

    document.addEventListener('click', () => {
        getEl('server-options-dropdown')?.classList.add('hidden');
    });
});

