auth.onAuthStateChanged(async (user) => {
  const loginView = document.getElementById('login-view');
  const appView = document.getElementById('app-view');
  if (user) {
    const userDocRef = db.collection('users').doc(user.uid);
    const userDoc = await userDocRef.get();
    if (!userDoc.exists) {
        const displayName = user.displayName || user.email.split('@')[0];
        const photoURL = user.photoURL || `https://i.pravatar.cc/64?u=${user.uid}`;
        await userDocRef.set({ displayName, photoURL, status: 'online', friends: [], blockedUsers: [] });
    } else {
        await userDocRef.update({ status: 'online' });
    }
    currentUser = { uid: user.uid, ... (await userDocRef.get()).data() };
    loginView.classList.add('hidden');
    appView.classList.remove('hidden');
    renderUserInfo();
    loadServers();
    loadFriends();
    setupCallListener();
    setupInvitationsListener();
    selectHome();
  } else {
    currentUser = null;
    loginView.classList.remove('hidden');
    appView.classList.add('hidden');
    [serversUnsubscribe, channelUnsubscribe, messageUnsubscribe, usersUnsubscribe, friendsUnsubscribe, callListenerUnsubscribe, invitationsUnsubscribe].forEach(unsub => unsub());
  }
});

