// =================================================================================
// Command Logic
// =================================================================================
async function handleSystemCommand(text) {
    const parts = text.split(' ');
    const cmd = parts[0].toLowerCase();
    const args = parts.slice(1).join(' ');

    const systemResponse = async (txt) => {
        const msg = {
            user: { uid: 'system', displayName: 'Conflict Assistant', photoURL: 'https://cdn-icons-png.flaticon.com/512/4712/4712109.png' },
            text: txt,
            timestamp: firebase.firestore.FieldValue.serverTimestamp()
        };
        await sendMessage(msg);
    };

    switch (cmd) {
        case '/ai':
            if (!args) return systemResponse("Please provide a prompt. Example: `/ai how does photosynthesis work?` ");
            systemResponse("Thinking...");
            const aiRes = await aiClient.models.generateContent({ model: 'gemini-3-flash-preview', contents: args });
            return systemResponse(`**Gemini:** ${aiRes.text}`);

        case '/summarize':
            if (currentMessagesCache.length === 0) return systemResponse("Nothing to summarize!");
            const history = currentMessagesCache.slice(-10).map(m => `${m.user.displayName}: ${m.text}`).join('\n');
            const summaryRes = await aiClient.models.generateContent({ 
                model: 'gemini-3-flash-preview', 
                contents: `Summarize this conversation in 2 sentences:\n${history}` 
            });
            return systemResponse(`**Summary of last 10 messages:** ${summaryRes.text}`);

        case '/weather':
            const city = args || 'London';
            const wRes = await aiClient.models.generateContent({ 
                model: 'gemini-3-flash-preview', 
                contents: `Give a short, fun, fictional weather report for ${city} using emojis.` 
            });
            return systemResponse(`**Forecast for ${city}:** ${wRes.text}`);

        case '/slap':
            return sendMessage({
                user: { uid: currentUser.uid, displayName: currentUser.displayName, photoURL: currentUser.photoURL },
                text: `*slaps ${args || 'everyone'} with a large trout!* 🐟`,
                timestamp: firebase.firestore.FieldValue.serverTimestamp()
            });

        case '/clear':
            document.getElementById('message-list').innerHTML = '';
            return true;

        case '/remind':
            const [sec, ...remindParts] = args.split(' ');
            const remindMsg = remindParts.join(' ');
            const delay = parseInt(sec);
            if (isNaN(delay)) return systemResponse("Usage: `/remind 60 feed the cat` ");
            systemResponse(`Reminder set for ${delay} seconds.`);
            setTimeout(() => {
                new Notification("Conflict Reminder", { body: remindMsg });
                systemResponse(`⏰ **Reminder:** ${remindMsg}`);
            }, delay * 1000);
            return true;
    }
    return false;
}

