window.selectHome = async () => {
    activeView = 'home';
    activeServerId = null;
    activeChannelId = null;
    document.getElementById('home-view').style.display = 'flex';
    document.getElementById('channel-list-panel').style.display = 'none';
    document.getElementById('chat-view').style.display = 'none';
    document.getElementById('placeholder-view').style.display = 'flex';
    document.getElementById('user-list-aside').style.display = 'none';
    loadServers();
    loadFriends();
    renderDashboard();
};

window.selectServer = (id) => {
    activeView = 'servers';
    activeServerId = id;
    activeChannelId = null;
    document.getElementById('home-view').style.display = 'none';
    document.getElementById('channel-list-panel').style.display = 'flex';
    document.getElementById('user-list-aside').style.display = 'block';

    db.collection('servers').doc(id).onSnapshot(doc => {
        activeServerData = { id: doc.id, ...doc.data() };
        document.getElementById('server-name-text').textContent = activeServerData.name;
    });

    db.collection('servers').doc(id).collection('channels').orderBy('name').onSnapshot(snap => {
        const channels = snap.docs.map(d => ({ id: d.id, ...d.data() }));
        const container = document.getElementById('channel-list');
        container.innerHTML = '<h2 class="text-xs font-bold text-gray-400 uppercase px-2 pt-4 pb-1">Text Channels</h2>';
        channels.forEach(c => {
            const active = activeChannelId === c.id;
            container.innerHTML += `
                <button onclick="window.selectChannel('${c.id}')" class="flex items-center w-full px-2 py-1.5 rounded-md mt-0.5 ${active ? 'bg-gray-700 text-white' : 'text-gray-400 hover:bg-gray-700/50'}">
                    <span class="mr-2 text-gray-500 font-bold">#</span>
                    <span class="truncate">${c.name}</span>
                </button>
            `;
        });
        if (!activeChannelId && channels.length > 0) window.selectChannel(channels[0].id);
    });
    loadServers();
};

window.selectChannel = (id) => {
    activeChannelId = id;
    document.getElementById('placeholder-view').style.display = 'none';
    document.getElementById('chat-view').style.display = 'flex';

    db.collection('servers').doc(activeServerId).collection('channels').doc(id).get().then(doc => {
        const data = doc.data();
        document.getElementById('chat-header').innerHTML = `<h2 class="font-bold text-lg text-white"># ${data.name}</h2>`;
        document.getElementById('message-input').placeholder = `Message #${data.name}`;
    });

    if (messageUnsubscribe) messageUnsubscribe();
    messageUnsubscribe = db.collection('servers').doc(activeServerId).collection('channels').doc(id).collection('messages').orderBy('timestamp', 'asc').onSnapshot(snap => {
        renderMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
};

window.selectDmChannel = (friendId) => {
    const id = getDmChannelId(friendId);
    activeChannelId = id;
    document.getElementById('placeholder-view').style.display = 'none';
    document.getElementById('chat-view').style.display = 'flex';

    db.collection('users').doc(friendId).get().then(doc => {
        const f = doc.data();
        document.getElementById('chat-header').innerHTML = `<h2 class="font-bold text-lg text-white">@ ${f.displayName}</h2>`;
        document.getElementById('message-input').placeholder = `Message @${f.displayName}`;
    });

    if (messageUnsubscribe) messageUnsubscribe();
    messageUnsubscribe = db.collection('dms').doc(id).collection('messages').orderBy('timestamp', 'asc').onSnapshot(snap => {
        renderMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    loadFriends();
};

const sendMessage = async (msg) => {
    if (activeView === 'servers') {
        await db.collection('servers').doc(activeServerId).collection('channels').doc(activeChannelId).collection('messages').add(msg);
    } else {
        await db.collection('dms').doc(activeChannelId).collection('messages').add(msg);
    }
};

const loadServers = () => {
    if (serversUnsubscribe) serversUnsubscribe();
    serversUnsubscribe = db.collection('servers').where('members', 'array-contains', currentUser.uid).onSnapshot(snap => {
        renderServers(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
};

const loadFriends = () => {
    if (friendsUnsubscribe) friendsUnsubscribe();
    friendsUnsubscribe = db.collection('users').doc(currentUser.uid).onSnapshot(async doc => {
        const ids = doc.data().friends || [];
        if (ids.length > 0) {
            const snap = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', ids).get();
            renderFriends(snap.docs.map(d => ({ id: d.id, ...d.data() })));
        } else {
            renderFriends([]);
        }
    });
};

