const handleIncomingCall = (data, id) => {
    activeCallData = { id, ...data };
    const view = document.getElementById('video-call-view');
    const status = document.getElementById('video-call-status');
    const controls = document.getElementById('video-call-controls');
    view.classList.remove('hidden');
    status.innerHTML = `<h2 class="text-xl font-bold mb-4">Incoming Call...</h2>`;
    controls.innerHTML = `
        <button onclick="window.answerCall()" class="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center hover:bg-green-600">Answer</button>
        <button onclick="window.hangUp()" class="w-16 h-16 bg-red-500 rounded-full flex items-center justify-center hover:bg-red-600">${HANGUP_SVG}</button>
    `;
};

window.startCall = async (fId) => {
    try {
        localStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
        document.getElementById('local-video').srcObject = localStream;
    } catch { return alert("Media access denied."); }

    const ref = db.collection('calls').doc();
    activeCallData = { id: ref.id, callerId: currentUser.uid, calleeId: fId, status: 'ringing' };

    document.getElementById('video-call-view').classList.remove('hidden');
    document.getElementById('video-call-status').innerHTML = `<h2 class="text-xl font-bold">Calling...</h2>`;
    document.getElementById('video-call-controls').innerHTML = `<button onclick="window.hangUp()" class="w-16 h-16 bg-red-500 rounded-full flex items-center justify-center">${HANGUP_SVG}</button>`;

    peerConnection = new RTCPeerConnection(iceServers);
    localStream.getTracks().forEach(t => peerConnection.addTrack(t, localStream));
    peerConnection.onicecandidate = e => { if (e.candidate) ref.collection('callerCandidates').add(e.candidate.toJSON()); };
    peerConnection.ontrack = e => { e.streams[0].getTracks().forEach(t => remoteStream.addTrack(t)); document.getElementById('remote-video').srcObject = remoteStream; };

    const offer = await peerConnection.createOffer();
    await peerConnection.setLocalDescription(offer);
    await ref.set({ ...activeCallData, offer: { type: offer.type, sdp: offer.sdp } });

    ref.onSnapshot(async s => {
        const d = s.data();
        if (d?.answer && !peerConnection.currentRemoteDescription) await peerConnection.setRemoteDescription(new RTCSessionDescription(d.answer));
        if (d?.status === 'ended') window.hangUp();
    });
};

window.answerCall = async () => {
    localStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
    document.getElementById('local-video').srcObject = localStream;

    const ref = db.collection('calls').doc(activeCallData.id);
    peerConnection = new RTCPeerConnection(iceServers);
    localStream.getTracks().forEach(t => peerConnection.addTrack(t, localStream));
    peerConnection.onicecandidate = e => { if (e.candidate) ref.collection('calleeCandidates').add(e.candidate.toJSON()); };
    peerConnection.ontrack = e => { e.streams[0].getTracks().forEach(t => remoteStream.addTrack(t)); document.getElementById('remote-video').srcObject = remoteStream; };

    const doc = await ref.get();
    await peerConnection.setRemoteDescription(new RTCSessionDescription(doc.data().offer));
    const answer = await peerConnection.createAnswer();
    await peerConnection.setLocalDescription(answer);
    await ref.update({ answer: { type: answer.type, sdp: answer.sdp }, status: 'connected' });

    document.getElementById('video-call-status').innerHTML = '';
    document.getElementById('video-call-controls').innerHTML = `
        <button onclick="window.toggleMute()" id="mute-btn" class="p-4 bg-gray-600 rounded-full">${MIC_ON_SVG}</button>
        <button onclick="window.hangUp()" class="w-16 h-16 bg-red-500 rounded-full flex items-center justify-center">${HANGUP_SVG}</button>
    `;
};

window.hangUp = async () => {
    if (peerConnection) peerConnection.close();
    if (localStream) localStream.getTracks().forEach(t => t.stop());
    document.getElementById('video-call-view').classList.add('hidden');
    if (activeCallData) await db.collection('calls').doc(activeCallData.id).update({ status: 'ended' });
    activeCallData = null;
};

