const isValidHttpUrl = (s) => { if (!s) return false; try { const u = new URL(s); return u.protocol === 'http:' || u.protocol === 'https:'; } catch { return false; } };
const escapeHTML = (s) => s ? s.replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])) : '';

function formatMessageText(text) {
    if (!text) return '';
    let escapedText = escapeHTML(text);

    // Code blocks
    escapedText = escapedText.replace(/```txt\n([\s\S]*?)\n```/g, (match, content) => {
        return `<pre class="bg-gray-900 p-2 rounded-md text-sm text-gray-300 whitespace-pre-wrap break-all mt-2"><code>${content}</code></pre>`;
    });

    // Mentions
    const mentionRegex = /@([a-zA-Z0-9_-]+)/g;
    escapedText = escapedText.replace(mentionRegex, (match, username) => {
        const user = Object.values(activeServerUserProfiles).find(u => u.displayName === username);
        if (user) {
            return `<span class="bg-blue-500/30 text-blue-400 font-bold px-1 rounded cursor-pointer mention" data-userid="${user.id}">@${username}</span>`;
        }
        return match;
    });

    return escapedText;
}

