    input.value = '';
    document.getElementById('command-suggestions').classList.add('hidden');

    if (val.startsWith('/slap')) {
        const target = val.split(' ')[1] || 'the air';
        val = `*slaps ${target} hard!* \n\`\`\`txt\n${SLAP_ASCII}\n\`\`\``;
    }

    const msg = {
        user: { uid: currentUser.uid, displayName: currentUser.displayName, photoURL: currentUser.photoURL },
        text: val,
        timestamp: firebase.firestore.FieldValue.serverTimestamp()
    };

    if (activeView === 'servers' && activeServerId && activeChannelId) {
        await db.collection('servers').doc(activeServerId).collection('channels').doc(activeChannelId).collection('messages').add(msg);
    } else if (activeView === 'home' && activeChannelId) {
        await db.collection('dms').doc(activeChannelId).collection('messages').add(msg);
    }
};

document.getElementById('message-input').oninput = (e) => {
    const text = e.target.value;
    const suggestions = document.getElementById('command-suggestions');
    if (text.startsWith('/')) {
        const term = text.substring(1).toLowerCase();
        const filtered = COMMANDS.filter(c => c.command.substring(1).startsWith(term));
        suggestions.innerHTML = filtered.map(c => `<button class="w-full text-left p-2 hover:bg-gray-700 text-sm" onclick="document.getElementById('message-input').value='${c.command} '; document.getElementById('message-input').focus();"><b>${c.command}</b> ${c.params} - ${c.description}</button>`).join('');
        suggestions.classList.toggle('hidden', filtered.length === 0);
    } else if (text.includes('@')) {
        const term = text.split('@').pop().toLowerCase();
        const filtered = Object.values(activeServerUserProfiles).filter(u => u.displayName.toLowerCase().startsWith(term));
        suggestions.innerHTML = filtered.map(u => `<button class="w-full text-left p-2 hover:bg-gray-700 text-sm" onclick="const v=document.getElementById('message-input').value; document.getElementById('message-input').value=v.substring(0, v.lastIndexOf('@')) + '@${u.displayName} '; document.getElementById('message-input').focus();">${u.displayName}</button>`).join('');
        suggestions.classList.toggle('hidden', filtered.length === 0);
    } else {
        suggestions.classList.add('hidden');
    }
};

