    if (!text) return '';
    let escapedText = escapeHTML(text);

    // Code blocks
    escapedText = escapedText.replace(/```txt\n([\s\S]*?)\n```/g, (match, content) => {
        return `<pre class="bg-gray-900 p-2 rounded-md text-sm text-gray-300 whitespace-pre-wrap break-all mt-2 font-mono"><code>${content}</code></pre>`;
    });

    // Mentions
    const mentionRegex = /@([a-zA-Z0-9_-]+)/g;
    escapedText = escapedText.replace(mentionRegex, (match, username) => {
        // Check both server profiles and current user
        const user = Object.values(activeServerUserProfiles).find(u => u.displayName === username);
        if (user || username === currentUser?.displayName) {
            return `<span class="bg-blue-500/30 text-blue-400 font-bold px-1 rounded cursor-pointer">@${username}</span>`;
        }
        return match;
    });

    return escapedText;
}

