    loadServers();
};

window.selectServer = (id) => {
    activeView = 'servers';
    activeServerId = id;
    activeChannelId = null;
    document.getElementById('home-view').style.display = 'none';
    document.getElementById('channel-list-panel').classList.remove('hidden');
    document.getElementById('channel-list-panel').style.display = 'flex';
    document.getElementById('user-list-aside').style.display = 'block';

    const serverRef = db.collection('servers').doc(id);
    if (usersUnsubscribe) usersUnsubscribe();
    usersUnsubscribe = serverRef.onSnapshot(async doc => {
        const data = doc.data();
        if (!data) return;
        document.getElementById('server-name-text').textContent = data.name;

        const memberUIDs = data.members || [];
        if (memberUIDs.length > 0) {
            const userDocs = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', memberUIDs).get();
            activeServerUserProfiles = {};
            userDocs.docs.forEach(d => activeServerUserProfiles[d.id] = { id: d.id, ...d.data() });
            renderUsers(activeServerUserProfiles);
        }
    });

    if (channelUnsubscribe) channelUnsubscribe();
    channelUnsubscribe = serverRef.collection('channels').orderBy('name').onSnapshot(snap => {
        const channels = snap.docs.map(d => ({ id: d.id, ...d.data() }));
        const container = document.getElementById('channel-list');
        container.innerHTML = `<h2 class="text-[10px] font-bold uppercase text-gray-500 px-2 py-4 tracking-widest">Text Channels</h2>`;
        channels.forEach(c => {
            const active = activeChannelId === c.id;
            const btn = document.createElement('button');
            btn.className = `flex items-center w-full px-2 py-1.5 rounded-md mb-0.5 text-left truncate transition-colors ${active ? 'bg-gray-700 text-white' : 'text-gray-400 hover:bg-gray-700/50 hover:text-gray-300'}`;
            btn.innerHTML = `<span class="mr-2 text-gray-500 font-bold">#</span>${escapeHTML(c.name)}`;
            btn.onclick = () => window.selectChannel(c.id);
            container.appendChild(btn);
        });
        if (!activeChannelId && channels.length > 0) window.selectChannel(channels[0].id);
    });
};

window.selectChannel = (id) => {
    activeChannelId = id;
    document.getElementById('placeholder-view').style.display = 'none';
    document.getElementById('chat-view').classList.remove('hidden');
    document.getElementById('chat-view').style.display = 'flex';

    db.collection('servers').doc(activeServerId).collection('channels').doc(id).get().then(doc => {
        document.getElementById('chat-header').innerHTML = `<h2 class="font-bold text-white"><span class="text-gray-500 mr-2">#</span>${escapeHTML(doc.data().name)}</h2>`;
    });

    if (messageUnsubscribe) messageUnsubscribe();
    messageUnsubscribe = db.collection('servers').doc(activeServerId).collection('channels').doc(id).collection('messages').orderBy('timestamp', 'asc').onSnapshot(snap => {
        const msgs = snap.docs.map(d => ({ id: d.id, ...d.data() }));

        // Handle notifications
        const lastMsg = msgs[msgs.length - 1];
        if (lastMsg && lastMsg.user.uid !== currentUser.uid && !document.hasFocus()) {
            popSound.play().catch(() => {});
        }

        renderMessages(msgs);
    });
};

window.selectDmChannel = (fId) => {
    const id = getDmChannelId(fId);
    activeChannelId = id;
    document.getElementById('placeholder-view').style.display = 'none';
    document.getElementById('chat-view').classList.remove('hidden');
    document.getElementById('chat-view').style.display = 'flex';

    db.collection('users').doc(fId).get().then(doc => {
        const f = doc.data();
        document.getElementById('chat-header').innerHTML = `<h2 class="font-bold text-white"><span class="text-gray-500 mr-2">@</span>${escapeHTML(f.displayName)}</h2>`;
    });

    if (messageUnsubscribe) messageUnsubscribe();
    messageUnsubscribe = db.collection('dms').doc(id).collection('messages').orderBy('timestamp', 'asc').onSnapshot(snap => {
        const msgs = snap.docs.map(d => ({ id: d.id, ...d.data() }));
        const lastMsg = msgs[msgs.length - 1];
        if (lastMsg && lastMsg.user.uid !== currentUser.uid && !document.hasFocus()) {
            popSound.play().catch(() => {});
        }
        renderMessages(msgs);
    });
};

const loadServers = () => {
    if (serversUnsubscribe) serversUnsubscribe();
    serversUnsubscribe = db.collection('servers').where('members', 'array-contains', currentUser.uid).onSnapshot(snap => {
        renderServers(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
};

const loadFriends = () => {
    if (friendsUnsubscribe) friendsUnsubscribe();
    friendsUnsubscribe = db.collection('users').doc(currentUser.uid).onSnapshot(async doc => {
        const ids = doc.data().friends || [];
        const container = document.getElementById('friend-list');
        container.innerHTML = `<h2 class="text-[10px] font-bold uppercase text-gray-500 px-2 py-4 tracking-widest">Direct Messages</h2>`;
        if (ids.length > 0) {
            const snap = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', ids).get();
            snap.docs.forEach(d => {
                const f = d.data();
                const btn = document.createElement('button');
                btn.className = "flex items-center w-full px-2 py-1.5 rounded-md text-gray-400 hover:bg-gray-700/50 transition-colors mb-0.5";
