    const serverRef = db.collection('servers').doc(id);
    if (usersUnsubscribe) usersUnsubscribe();
    usersUnsubscribe = serverRef.onSnapshot(async doc => {
        const data = doc.data();
        if (!data) return;
        document.getElementById('server-name-text').textContent = data.name;

        const memberUIDs = data.members || [];
        if (memberUIDs.length > 0) {
            const userDocs = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', memberUIDs).get();
            activeServerUserProfiles = {};
            userDocs.docs.forEach(d => activeServerUserProfiles[d.id] = { id: d.id, ...d.data() });
