document.getElementById('message-form').onsubmit = async (e) => {
    e.preventDefault();
    const input = document.getElementById('message-input');
    let val = input.value.trim();
    if (!val || !currentUser) return;

    input.value = '';
    document.getElementById('command-suggestions').classList.add('hidden');

    // Handle /slap command
    if (val.startsWith('/slap')) {
        const target = val.split(' ')[1] || 'the air';
        val = `*slaps ${target} hard!* \n\`\`\`txt\n${SLAP_ASCII}\n\`\`\``;
    } else if (val === '/shrug') {
        val = '¯\\_(ツ)_/¯';
    } else if (val === '/coinflip') {
        val = `flipped a coin and got **${Math.random() > 0.5 ? 'Heads' : 'Tails'}**!`;
    } else if (val === '/dice') {
        val = `rolled a d6 and got **${Math.floor(Math.random() * 6) + 1}**!`;
    }

    const msg = {
        user: { uid: currentUser.uid, displayName: currentUser.displayName, photoURL: currentUser.photoURL },
        text: val,
        timestamp: firebase.firestore.FieldValue.serverTimestamp()
    };

    try {
        if (activeView === 'servers' && activeServerId && activeChannelId) {
            await db.collection('servers').doc(activeServerId).collection('channels').doc(activeChannelId).collection('messages').add(msg);
        } else if (activeView === 'home' && activeChannelId) {
            await db.collection('dms').doc(activeChannelId).collection('messages').add(msg);
        }
    } catch (err) {
        console.error("Message send failed:", err);
    }
};

// Suggestions logic
document.getElementById('message-input').oninput = (e) => {
    const text = e.target.value;
    const suggestions = document.getElementById('command-suggestions');
    if (text.startsWith('/')) {
        const term = text.substring(1).toLowerCase();
        const filtered = COMMANDS.filter(c => c.command.substring(1).startsWith(term));
        suggestions.innerHTML = filtered.map(c => `
            <button class="w-full text-left p-2 hover:bg-gray-700 rounded-md transition-colors" onclick="document.getElementById('message-input').value='${c.command} '; document.getElementById('message-input').focus(); document.getElementById('command-suggestions').classList.add('hidden');">
