            </button>
        `).join('');
        suggestions.classList.toggle('hidden', filtered.length === 0);
    } else if (text.includes('@')) {
        const parts = text.split('@');
        const term = parts[parts.length - 1].toLowerCase();
        const filtered = Object.values(activeServerUserProfiles).filter(u => u.displayName.toLowerCase().startsWith(term));
