function escapeHTML(str: string) {
    return str.replace(/[&<>"']/g, (m) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
}

function formatMessage(text: string) {
    if (!text) return '';
    let escaped = escapeHTML(text);
    // Mentions
    const mentionRegex = /@([a-zA-Z0-9_-]+)/g;
    escaped = escaped.replace(mentionRegex, (match, username) => {
        const isMe = currentUser && username === currentUser.displayName;
        return `<span class="px-1 font-bold rounded ${isMe ? 'bg-yellow-500/20 text-yellow-200' : 'bg-blue-500/20 text-blue-300'}">@${username}</span>`;
    });
    // Multi-line code
    escaped = escaped.replace(/```txt\n([\s\S]*?)\n```/g, '<pre class="bg-gray-900 p-2 rounded mt-2 text-xs font-mono border border-gray-600 whitespace-pre"><code>$1</code></pre>');
    return escaped;
}

