async function selectServer(id: string) {
    activeView = 'servers';
    activeServerId = id;
    activeChannelId = null;
    document.getElementById('home-view')?.classList.add('hidden');
    document.getElementById('channel-list-panel')?.classList.remove('hidden');
    document.getElementById('user-list-aside')?.classList.remove('hidden');

    const serverRef = db.collection('servers').doc(id);

    // Subscribe to members
    if (usersUnsub) usersUnsub();
    usersUnsub = serverRef.onSnapshot(async doc => {
        const data = doc.data();
        if (!data) return;
        const nameEl = document.getElementById('server-name-text');
        if (nameEl) nameEl.textContent = data.name;

        const memberIds = data.members || [];
        if (memberIds.length > 0) {
            const snap = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', memberIds).get();
            activeServerMembers = {};
            snap.docs.forEach(d => activeServerMembers[d.id] = { id: d.id, ...d.data() });
            renderUserList(activeServerMembers);
        }
    });

    // Subscribe to channels
    if (channelUnsub) channelUnsub();
    channelUnsub = serverRef.collection('channels').orderBy('name').onSnapshot(snap => {
        const channels = snap.docs.map(d => ({ id: d.id, ...d.data() }));
        const container = document.getElementById('channel-list');
        if (!container) return;
        container.innerHTML = `<h2 class="text-[10px] font-bold uppercase text-gray-500 px-2 py-4 tracking-widest">Channels</h2>`;
        channels.forEach((c: any) => {
            const btn = document.createElement('button');
            btn.className = `flex items-center w-full px-2 py-1.5 rounded-md mb-0.5 text-left truncate transition-colors ${activeChannelId === c.id ? 'bg-gray-700 text-white' : 'text-gray-400 hover:bg-gray-700/50 hover:text-gray-300'}`;
            btn.innerHTML = `<span class="mr-2 text-gray-500 font-bold">#</span>${escapeHTML(c.name)}`;
            btn.onclick = () => selectChannel(c.id);
            container.appendChild(btn);
        });
        if (!activeChannelId && channels.length > 0) selectChannel(channels[0].id);
    });
}

function selectChannel(id: string) {
    activeChannelId = id;
    document.getElementById('placeholder-view')?.classList.add('hidden');
    document.getElementById('chat-view')?.classList.remove('hidden');

    db.collection('servers').doc(activeServerId!).collection('channels').doc(id).get().then(doc => {
        const header = document.getElementById('chat-header');
        if (header) header.innerHTML = `<h2 class="font-bold text-white flex items-center"><span class="text-gray-500 mr-2">#</span>${escapeHTML(doc.data()?.name || '')}</h2>`;
    });

    if (messageUnsub) messageUnsub();
    messageUnsub = db.collection('servers').doc(activeServerId!).collection('channels').doc(id).collection('messages').orderBy('timestamp', 'asc').onSnapshot(snap => {
        snap.docChanges().forEach(change => {
            if (change.type === 'added') {
                const msg = change.doc.data();
                if (msg.user.uid !== currentUser.uid && msg.timestamp) {
                    const isMentioned = msg.text?.includes(`@${currentUser.displayName}`);
                    if (isMentioned) {
                        if (userInteracted) popSound.play().catch(() => {});
                        if (Notification.permission === 'granted' && !document.hasFocus()) {
                            new Notification(`Mentioned by ${msg.user.displayName}`, { body: msg.text.substring(0, 50) });
                        }
                    }
                }
            }
        });
        renderMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
}

function selectDmChannel(fId: string) {
    const id = [currentUser.uid, fId].sort().join('_');
    activeChannelId = id;
    activeServerId = null;
    document.getElementById('placeholder-view')?.classList.add('hidden');
    document.getElementById('chat-view')?.classList.remove('hidden');

    db.collection('users').doc(fId).get().then(doc => {
        const header = document.getElementById('chat-header');
        if (header) header.innerHTML = `<h2 class="font-bold text-white flex items-center"><span class="text-gray-500 mr-2">@</span>${escapeHTML(doc.data()?.displayName || '')}</h2>`;
    });

    if (messageUnsub) messageUnsub();
    messageUnsub = db.collection('dms').doc(id).collection('messages').orderBy('timestamp', 'asc').onSnapshot(snap => {
        snap.docChanges().forEach(change => {
            if (change.type === 'added') {
                const msg = change.doc.data();
                if (msg.user.uid !== currentUser.uid && msg.timestamp) {
                    if (userInteracted) popSound.play().catch(() => {});
                }
            }
        });
        renderMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
}

