function renderServerList(servers: any[] = []) {
    const container = document.getElementById('server-list');
    if (!container) return;
    container.innerHTML = '';

    const homeBtn = document.createElement('button');
    homeBtn.className = `w-12 h-12 mb-2 rounded-3xl hover:rounded-2xl transition-all duration-200 flex items-center justify-center ${activeView === 'home' ? 'bg-blue-500 rounded-2xl' : 'bg-gray-700'}`;
    homeBtn.innerHTML = `<svg class="w-7 h-7 text-white" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>`;
    homeBtn.onclick = selectHome;
    container.appendChild(homeBtn);

    servers.forEach(s => {
        const btn = document.createElement('button');
        const isActive = activeServerId === s.id;
        btn.className = `w-12 h-12 mb-2 rounded-3xl hover:rounded-2xl transition-all duration-200 overflow-hidden ${isActive ? 'bg-blue-500 rounded-2xl' : 'bg-gray-700'}`;
        btn.innerHTML = s.iconUrl ? `<img src="${s.iconUrl}" class="w-full h-full object-cover" />` : `<span class="text-white font-bold">${s.name.charAt(0).toUpperCase()}</span>`;
        btn.onclick = () => selectServer(s.id);
        container.appendChild(btn);
    });
}

function renderMessages(messages: any[]) {
    const container = document.getElementById('message-list');
    if (!container) return;
    container.innerHTML = '';
    messages.forEach(m => {
        const isMentioned = m.text?.includes(`@${currentUser.displayName}`);
        const avatar = m.user.photoURL || DEFAULT_AVATAR;
        const time = m.timestamp ? new Date(m.timestamp.toDate()).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '...';

        container.innerHTML += `
            <div class="flex px-4 py-2 hover:bg-gray-800/50 group transition-all duration-200 ${isMentioned ? 'mention-highlight' : ''}">
                <img src="${avatar}" class="w-10 h-10 rounded-full object-cover mr-4 flex-shrink-0" />
                <div class="flex-1 min-w-0">
                    <div class="flex items-baseline space-x-2">
                        <span class="font-bold text-white hover:underline cursor-pointer">${escapeHTML(m.user.displayName)}</span>
                        <span class="text-[10px] text-gray-500">${time}</span>
                    </div>
                    <div class="text-gray-300 text-sm break-words whitespace-pre-wrap leading-relaxed">${formatMessage(m.text)}</div>
                </div>
            </div>
        `;
    });
    container.scrollTop = container.scrollHeight;
}

function renderUserList(users: any) {
    const container = document.getElementById('user-list-aside');
    if (!container) return;
    container.innerHTML = `<h3 class="text-xs font-bold uppercase text-gray-500 px-4 pt-4 pb-2">Members — ${Object.keys(users).length}</h3>`;
