let channelUnsub = () => {};
let serversUnsub = () => {};
let friendsUnsub = () => {};

// =================================================================================
// Utils
// =================================================================================
const escapeHTML = (s) => s ? s.replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])) : '';

function formatText(text) {
    if (!text) return '';
    let escaped = escapeHTML(text);

    // Mentions highlighting
    if (currentUser) {
        const mentionRegex = /@([a-zA-Z0-9_-]+)/g;
        escaped = escaped.replace(mentionRegex, (match, username) => {
            const isMe = username.toLowerCase() === currentUser.displayName.toLowerCase();
            return `<span class="px-1 font-bold rounded ${isMe ? 'bg-yellow-500/20 text-yellow-200' : 'bg-blue-500/20 text-blue-300'}">@${username}</span>`;
        });
    }

    // Code blocks
    escaped = escaped.replace(/```txt\n([\s\S]*?)\n```/g, '<pre class="bg-gray-900 p-2 rounded mt-2 text-xs font-mono border border-gray-600 overflow-x-auto"><code>$1</code></pre>');

    return escaped;
}

const displayRandomAd = () => {
    const ad = FAKE_ADS[Math.floor(Math.random() * FAKE_ADS.length)];
    const adLink = document.getElementById('channel-ad-link');
    if (adLink) {
        adLink.href = ad.link;
        adLink.querySelector('[data-ad-title]').textContent = ad.title;
        adLink.querySelector('[data-ad-body]').textContent = ad.body;
    }
};

