function selectHome() {
    activeView = 'home';
    activeServerId = null;
    activeChannelId = null;

    document.getElementById('server-header').textContent = 'Home';
    document.getElementById('placeholder-view').classList.remove('hidden');
    document.getElementById('chat-view').classList.add('hidden');
    document.getElementById('member-sidebar').classList.add('hidden');

    renderServers();
    loadFriends();
    displayRandomAd();
}

async function selectServer(id) {
    activeView = 'servers';
    activeServerId = id;
    activeChannelId = null;

    const serverRef = db.collection('servers').doc(id);
    const doc = await serverRef.get();
    if (!doc.exists) return;

    const data = doc.data();
    document.getElementById('server-header').textContent = data.name;
    document.getElementById('member-sidebar').classList.remove('hidden');

    renderServers();

    // Load Channels
    if (channelUnsub) channelUnsub();
    channelUnsub = serverRef.collection('channels').orderBy('name').onSnapshot(snap => {
        const container = document.getElementById('channel-list');
        container.innerHTML = `<h3 class="text-[10px] font-bold uppercase text-gray-500 px-2 py-2 tracking-widest">Text Channels</h3>`;
        snap.docs.forEach(d => {
            const c = { id: d.id, ...d.data() };
            const btn = document.createElement('button');
            const active = activeChannelId === c.id;
            btn.className = `flex items-center w-full px-2 py-1.5 rounded-md text-sm transition-colors ${active ? 'bg-gray-700 text-white' : 'text-gray-400 hover:bg-gray-700/50 hover:text-gray-300'}`;
            btn.innerHTML = `<span class="mr-2 opacity-50 font-bold">#</span> ${escapeHTML(c.name)}`;
            btn.onclick = () => selectChannel(c.id);
            container.appendChild(btn);
        });
        if (!activeChannelId && snap.docs.length > 0) selectChannel(snap.docs[0].id);
    });

    // Load Members
    const memberIds = data.members || [];
    if (memberIds.length > 0) {
        const usersSnap = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', memberIds.slice(0, 10)).get();
        activeMemberProfiles = {};
        const list = document.getElementById('member-list');
        list.innerHTML = `<h3 class="text-[10px] font-bold uppercase text-gray-500 px-2 pt-4 pb-2 tracking-widest">Members — ${memberIds.length}</h3>`;
        usersSnap.docs.forEach(d => {
            const u = d.data();
            activeMemberProfiles[d.id] = u;
            const item = document.createElement('div');
            item.className = "flex items-center px-2 py-1.5 hover:bg-gray-700/30 rounded-md cursor-pointer group transition-all";
            item.innerHTML = `
                <img src="${u.photoURL || DEFAULT_AVATAR}" class="w-8 h-8 rounded-full object-cover mr-3 grayscale group-hover:grayscale-0 transition-all">
                <span class="text-sm font-medium text-gray-400 group-hover:text-white truncate">${escapeHTML(u.displayName)}</span>
            `;
            list.appendChild(item);
        });
    }
}

function selectChannel(id) {
    activeChannelId = id;
    document.getElementById('placeholder-view').classList.add('hidden');
    document.getElementById('chat-view').classList.remove('hidden');

    db.collection('servers').doc(activeServerId).collection('channels').doc(id).get().then(doc => {
        const header = document.getElementById('chat-header');
        header.innerHTML = `<div class="flex items-center font-bold text-white"><span class="text-gray-500 mr-2">#</span>${escapeHTML(doc.data().name)}</div>`;
    });

    if (messageUnsub) messageUnsub();
    messageUnsub = db.collection('servers').doc(activeServerId).collection('channels').doc(id).collection('messages').orderBy('timestamp', 'asc').limitToLast(50).onSnapshot(snap => {
        snap.docChanges().forEach(change => {
            if (change.type === 'added') {
                const msg = change.doc.data();
                if (msg.user.uid !== currentUser.uid && msg.timestamp) {
                    const isMentioned = msg.text?.includes(`@${currentUser.displayName}`);
                    if (isMentioned) {
                        NOTIFICATION_SOUND.play().catch(() => {});
                        if (Notification.permission === 'granted' && !document.hasFocus()) {
                            new Notification(`Mentioned by ${msg.user.displayName}`, { body: msg.text });
                        }
                    }
                }
            }
        });
        renderMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
}

function selectDmChannel(fId) {
    const dmId = [currentUser.uid, fId].sort().join('_');
    activeChannelId = dmId;
    activeServerId = null;

    document.getElementById('placeholder-view').classList.add('hidden');
    document.getElementById('chat-view').classList.remove('hidden');
    document.getElementById('member-sidebar').classList.add('hidden');

    db.collection('users').doc(fId).get().then(doc => {
        const u = doc.data();
        document.getElementById('chat-header').innerHTML = `<div class="flex items-center font-bold text-white"><span class="text-gray-500 mr-2">@</span>${escapeHTML(u.displayName)}</div>`;
    });

    if (messageUnsub) messageUnsub();
    messageUnsub = db.collection('dms').doc(dmId).collection('messages').orderBy('timestamp', 'asc').limitToLast(50).onSnapshot(snap => {
        renderMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
}

