function renderServers() {
    if (serversUnsub) serversUnsub();
    serversUnsub = db.collection('servers').where('members', 'array-contains', currentUser.uid).onSnapshot(snap => {
        const list = document.getElementById('server-list');
        list.innerHTML = '';

        // Home Button
        const homeBtn = document.createElement('button');
        const homeActive = activeView === 'home';
        homeBtn.className = `w-12 h-12 rounded-3xl hover:rounded-2xl transition-all flex items-center justify-center group relative ${homeActive ? 'bg-blue-500 rounded-2xl' : 'bg-gray-800'}`;
        homeBtn.innerHTML = `
            <div class="absolute -left-3 w-1 bg-white rounded-r-full transition-all ${homeActive ? 'h-10' : 'h-0 group-hover:h-5'}"></div>
            <svg class="w-7 h-7 text-white" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>
        `;
        homeBtn.onclick = selectHome;
        list.appendChild(homeBtn);
        list.appendChild(document.createElement('hr')).className = "w-8 border-gray-700 border-t-2 my-1";

        snap.docs.forEach(d => {
            const s = d.data();
            const active = activeServerId === d.id;
            const btn = document.createElement('button');
            btn.className = `w-12 h-12 rounded-3xl hover:rounded-2xl transition-all flex items-center justify-center group relative overflow-hidden ${active ? 'bg-blue-500 rounded-2xl' : 'bg-gray-800'}`;
            btn.innerHTML = `
                <div class="absolute -left-3 w-1 bg-white rounded-r-full transition-all ${active ? 'h-10' : 'h-0 group-hover:h-5'}"></div>
                ${s.iconUrl ? `<img src="${s.iconUrl}" class="w-full h-full object-cover">` : `<span class="text-white font-bold">${s.name.charAt(0)}</span>`}
            `;
            btn.onclick = () => selectServer(d.id);
            list.appendChild(btn);
        });
    });
}

function loadFriends() {
    if (friendsUnsub) friendsUnsub();
    friendsUnsub = db.collection('users').doc(currentUser.uid).onSnapshot(async doc => {
        const ids = doc.data()?.friends || [];
        const container = document.getElementById('channel-list');
        container.innerHTML = `<h3 class="text-[10px] font-bold uppercase text-gray-500 px-2 py-2 tracking-widest">Direct Messages</h3>`;
        if (ids.length > 0) {
            const snap = await db.collection('users').where(firebase.firestore.FieldPath.documentId(), 'in', ids).get();
            snap.docs.forEach(d => {
                const f = d.data();
                const btn = document.createElement('button');
                btn.className = `flex items-center w-full px-2 py-1.5 rounded-md text-sm text-gray-400 hover:bg-gray-700/50 hover:text-gray-300 transition-colors`;
                btn.innerHTML = `<span class="mr-2 opacity-50 font-bold">@</span> ${escapeHTML(f.displayName)}`;
                btn.onclick = () => selectDmChannel(d.id);
                container.appendChild(btn);
            });
        } else {
            container.innerHTML += `<p class="text-[10px] text-gray-600 px-2 italic">No friends yet</p>`;
        }
    });
}

function renderMessages(messages) {
    const list = document.getElementById('message-list');
    list.innerHTML = '';
    messages.forEach(m => {
        const isMe = m.user.uid === currentUser.uid;
        const isMentioned = m.text?.includes(`@${currentUser.displayName}`);
        const avatar = m.user.photoURL || DEFAULT_AVATAR;
        const time = m.timestamp ? new Date(m.timestamp.toDate()).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '...';

        list.innerHTML += `
            <div class="flex items-start px-2 py-1 hover:bg-black/10 group transition-all ${isMentioned ? 'mention-highlight' : ''}">
                <img src="${avatar}" class="w-10 h-10 rounded-full object-cover mr-4 flex-shrink-0 mt-1">
                <div class="flex-1 min-w-0">
                    <div class="flex items-baseline space-x-2">
                        <span class="font-bold text-white hover:underline cursor-pointer">${escapeHTML(m.user.displayName)}</span>
                        <span class="text-[10px] text-gray-500">${time}</span>
                    </div>
                    <div class="text-gray-300 text-sm leading-relaxed break-words">${formatText(m.text)}</div>
                </div>
            </div>
        `;
    });
    list.scrollTop = list.scrollHeight;
}

// =================================================================================
// Auth Logic
// =================================================================================
function signInWithGoogle() {
    auth.signInWithPopup(provider).catch(err => showError(err.message));
}

function handleSignUp(e) {
    e.preventDefault();
    const email = document.getElementById('signup-email').value;
    const pass = document.getElementById('signup-password').value;
    auth.createUserWithEmailAndPassword(email, pass).catch(err => showError(err.message));
}

function handleSignIn(e) {
    e.preventDefault();
    const email = document.getElementById('signin-email').value;
    const pass = document.getElementById('signin-password').value;
    auth.signInWithEmailAndPassword(email, pass).catch(err => showError(err.message));
}

function showError(msg) {
    const err = document.getElementById('login-error-container');
    err.textContent = msg;
    err.classList.remove('hidden');
}

auth.onAuthStateChanged(async user => {
    const login = document.getElementById('login-view');
    const app = document.getElementById('app-view');
    if (user) {
        const ref = db.collection('users').doc(user.uid);
        let doc = await ref.get();
        if (!doc.exists) {
            const dn = user.displayName || user.email.split('@')[0];
            const pu = user.photoURL || "";
            await ref.set({ displayName: dn, photoURL: pu, status: 'online', friends: [] });
            doc = await ref.get();
        }
        currentUser = { uid: user.uid, ...doc.data() };
        login.classList.add('hidden');
        app.classList.remove('hidden');

        // Profile Footer
        document.getElementById('user-info-footer').innerHTML = `
            <img src="${currentUser.photoURL || DEFAULT_AVATAR}" class="w-9 h-9 rounded-full object-cover mr-2 border border-gray-700">
            <div class="truncate">
                <p class="text-xs font-bold text-white truncate">${escapeHTML(currentUser.displayName)}</p>
                <p class="text-[9px] text-gray-500 uppercase tracking-tighter">Online</p>
            </div>
        `;

        selectHome();
        if (Notification.permission === 'default') Notification.requestPermission();
    } else {
        currentUser = null;
        login.classList.remove('hidden');
        app.classList.add('hidden');
    }
});

// =================================================================================
// Message Sending
// =================================================================================
document.getElementById('message-form').onsubmit = async (e) => {
    e.preventDefault();
    const input = document.getElementById('message-input');
    let val = input.value.trim();
    if (!val || !currentUser || !activeChannelId) return;

    input.value = '';

    // Handle Slap
    if (val.startsWith('/slap')) {
        const target = val.split(' ')[1] || 'the air';
        val = `*slaps ${target} with a large trout!* \n\`\`\`txt\n( \`д´)         (x_x)\n(     )つ      (     )\n /   \\          /   \\\n\`\`\``;
    } else if (val === '/coinflip') {
        val = `flipped a coin and got **${Math.random() > 0.5 ? 'Heads' : 'Tails'}**!`;
    }

    const msg = {
        user: { uid: currentUser.uid, displayName: currentUser.displayName, photoURL: currentUser.photoURL },
        text: val,
        timestamp: firebase.firestore.FieldValue.serverTimestamp()
    };

    if (activeServerId) {
        await db.collection('servers').doc(activeServerId).collection('channels').doc(activeChannelId).collection('messages').add(msg);
    } else {
        await db.collection('dms').doc(activeChannelId).collection('messages').add(msg);
    }
};

// =================================================================================
// Event Listeners
// =================================================================================
document.getElementById('login-button').onclick = signInWithGoogle;
document.getElementById('signup-form').onsubmit = handleSignUp;
document.getElementById('signin-form').onsubmit = handleSignIn;
document.getElementById('logout-btn').onclick = () => auth.signOut();
document.getElementById('show-signin').onclick = () => {
    document.getElementById('signup-form').classList.add('hidden');
    document.getElementById('signin-form').classList.remove('hidden');
};
document.getElementById('show-signup').onclick = () => {
    document.getElementById('signin-form').classList.add('hidden');
    document.getElementById('signup-form').classList.remove('hidden');
};

